const target = { connectionId: 'c', database: 'main' as const, table: 'subject' };
const tableSql = "CREATE TABLE subject(id INTEGER PRIMARY KEY,note TEXT DEFAULT (printf('%s','原表达式')),generated TEXT AS(note) VIRTUAL)";
const sql = ['CREATE TABLE main."candidate"(id INTEGER PRIMARY KEY,note TEXT)', 'INSERT INTO main."candidate" SELECT id,note FROM main."subject"', 'DROP TABLE main."subject"', 'ALTER TABLE main."candidate" RENAME TO "subject"'];
function catalogue(readOnly = false): SqliteTableRebuildInspectOutput { return { catalogueId: 'original-catalogue', target, readOnly, expiresAt: new Date(Date.now()+60000).toISOString(), tableSql, columns: [{cid:0,name:'id',declaredType:'INTEGER',notNull:false,defaultSql:null,primaryKey:1,hidden:0},{cid:1,name:'note',declaredType:'TEXT',notNull:false,defaultSql:"(printf('%s','原表达式'))",primaryKey:0,hidden:0},{cid:2,name:'generated',declaredType:'TEXT',notNull:false,defaultSql:null,primaryKey:0,hidden:2}], relatedObjects:[{type:'table',name:'subject',table:'subject',sql:tableSql},{type:'view',name:'view_note',table:'view_note',sql:'CREATE VIEW view_note AS SELECT note FROM subject'}], strict:false,withoutRowid:false,rowIdentity:{kind:'rowid',source:'id'}}; }
function outcome(kind: SqliteTableRebuildOutcome['outcome'] = 'committed'): SqliteTableRebuildOutcome { return {operationId:'original-operation',target,outcome:kind,message:'合成'+kind,definitionVerified:kind==='committed',fact:{operationId:'original-operation',target,phase:kind,requestedStatements:sql.length,completedStatements:kind==='not-sent'?0:sql.length,sourceRows:kind==='not-sent'?'0':'3',copiedRows:kind==='not-sent'?'0':'3',verifiedRows:kind==='not-sent'?'0':'3',commitMayHaveBeenSent:kind==='committed'||kind==='unknown',commitAcknowledged:kind==='committed',rollbackAcknowledged:kind==='rolled-back'}}; }
function deferred<T>() { let resolve!: (value:T)=>void,reject!:(reason:Error)=>void;const promise=new Promise<T>((yes,no)=>{resolve=yes;reject=no;});return{promise,resolve,reject}; }
function props(node:MemoryNode):Record<string,any>{const key=Object.keys(node).find(name=>name.startsWith('__reactProps$'));if(!key)throw Error('缺少React事件端口');return(node as any)[key];}
function control(label:string){const node=document.querySelector('[aria-label="'+label+'"]');expect(node,label).not.toBeNull();return node!;}
function button(label:string){const node=document.querySelectorAll('button').find(node=>node.textContent===label||node.getAttribute('aria-label')===label);expect(node,label).toBeDefined();return node!;}
async function click(label:string){const node=button(label);expect(node.disabled,label).toBe(false);await act(async()=>node.dispatchEvent(new MemoryEvent('click')));}
async function input(label:string,value:string){const node=control(label);expect(node.disabled,label).toBe(false);await act(async()=>props(node).onChange({target:{value}}));}
async function check(label:string,checked:boolean){const node=control(label);expect(node.disabled,label).toBe(false);await act(async()=>props(node).onChange({target:{checked}}));}
/** 仅四个IPC为合成RAM端口，完整Dialog/合同/schema/store与真实React事件处理器参与。 */
async function mount(readOnly=false,overrides:Partial<SqliteTableRebuildServices>={}){
  const profile:SqliteConnectionProfile={id:'c',name:'原SQLite',group:'',color:'#123456',dialect:'sqlite',sqlite:{filePath:'D:/synthetic/rebuild.sqlite',readOnly,busyTimeoutMs:1000}};
  useWorkspace.setState({connections:[profile],connectionVersions:{c:3},activeJobs:{}});
  const inspect=vi.fn<SqliteTableRebuildServices['inspect']>(async()=>catalogue(readOnly)),preview=vi.fn<SqliteTableRebuildServices['preview']>(async input=>({previewId:'preview-'+input.taskId,catalogueId:input.catalogueId,target,sql,changedTypes:input.changes.filter(change=>change.declaredType!==undefined).length,changedDefaults:input.changes.filter(change=>change.default!==undefined).length,...(input.foreignKeyEdits?{changedForeignKeys:input.foreignKeyEdits.length}:{}),...(input.checkEdits?{changedChecks:input.checkEdits.length}:{}),...(input.uniqueEdits?{changedUniques:input.uniqueEdits.length}:{}),...(input.primaryKeyEdit?{changedPrimaryKey:true as const}:{}),...(input.columnOrder?{changedOrder:true}:{}),warnings:['合成原风险提示'],confirmation:'main.subject',expiresAt:new Date(Date.now()+60000).toISOString()}));
  const apply=vi.fn<SqliteTableRebuildServices['apply']>(async()=>outcome()),release=vi.fn<SqliteTableRebuildServices['release']>(async()=>{}),cancel=vi.fn<SqliteTableRebuildServices['cancel']>(async()=>undefined);let listener!:(event:TaskEvent)=>void;
  const services:SqliteTableRebuildServices={inspect,preview,apply,release,cancel,subscribe:fn=>{listener=fn;return()=>{};},...overrides},onClose=vi.fn(),onApplied=vi.fn(),onDirtyChange=vi.fn(),onExecutionUncertain=vi.fn(),base={target,targetVersion:3,services,onClose,onApplied,onDirtyChange,onExecutionUncertain};
  const host=document.createElement('div');document.body.appendChild(host);root=createRoot(host as any);await act(async()=>root!.render(<Dialog {...base}/>));
  return{profile,inspect,preview,apply,release,cancel,onClose,onApplied,onDirtyChange,onExecutionUncertain,async emit(event:TaskEvent){await act(async()=>listener(event));},async rerender(patch:Partial<ComponentProps<typeof Dialog>>={}){await act(async()=>root!.render(<Dialog {...base} {...patch}/>));}};
}
async function design(){await click(text.read);await input(text.column,'note');await input(text.typeMode,'modify');await input(text.newType,'BLOB');}
async function ready(){await design();await click(text.preview);}
async function confirm(){await input(text.confirmation,'main.subject');for(const label of Object.values(text.riskLabels))await check(label,true);}
